import java.io.*;
import java.util.*;

import jakarta.servlet.*;
import jakarta.servlet.annotation.*;
import jakarta.servlet.http.*;
import com.bisangoding.web.*;

public class Main {
    public static void main(String[] args) {
        ServerUji server = new ServerUji();
        server.tambah(new FilterA());
        server.tambah(new FilterB());
        server.tambah(new HaloServlet());
        server.kirim("GET", "/halo");
        System.out.println(String.join(" > ", Jejak.urutan));
    }
