class Jejak {
    static final List<String> urutan = new ArrayList<>();
}

@WebFilter("/*")
class FilterA implements Filter {
    @Override
    public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain) throws IOException, ServletException {
        Jejak.urutan.add("A masuk");
        chain.doFilter(req, res);
        Jejak.urutan.add("A keluar");
    }
}

@WebFilter("/*")
class FilterB implements Filter {
    @Override
    public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain) throws IOException, ServletException {
        Jejak.urutan.add("B masuk");
        chain.doFilter(req, res);
        Jejak.urutan.add("B keluar");
    }
}

@WebServlet("/halo")
class HaloServlet extends HttpServlet {
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse res) {
        Jejak.urutan.add("servlet");
    }
}

